/**
 * Type of document
 *
 * A bizonylat típusa
 */
export type DocumentCategoryType = 'RECEIPT' | 'HEALTH' | 'FUEL' | 'CONSUME' | 'OTHER' | 'DEFERRED';

/**
 * Document class type, what document is sent by the e-cash register
 *
 * Bizonylat típus, milyen bizonylatot küld be az e-pénztárgép
 */
export type DocumentClassType =
  | 'RECEIPT'
  | 'FUEL'
  | 'HEALTH'
  | 'DEFERRED'
  | 'CONSUME'
  | 'SIMPLIFIEDINVOICE'
  | 'NORMALINVOICE'
  | 'OTHER';

/**
 * Document control data type
 *
 * Dokumentum adatszolgáltatás rész típusa
 */
export interface DocumentControlDataType {
  /**
   * Sequential number of the original document or modification document
   *
   * Dokumentum vagy módosító okirat sorszáma
   */
  documentNumber: string;
  /**
   * Serial number within the e-cash register (numbered 1 to 1). Strictly
   * monotonic ascending serial number, no skips
   *
   * Bejegyzés sorszám e-pénztárgépen belül (1-től sorszámozva). Szigorúan
   * monoton növekvő sorszám, nem lehet benne kihagyás.
   */
  recordCounter: number;
  /**
   * Information of balance change
   *
   * A fióktartalom változásának adatai
   */
  balanceChange: InstrumentType;
}

/**
 * Document exchange data type
 *
 * A dokumentum adatszolgáltatás adatok típusa
 *
 * @remarks At most one of `healthFundInfo`, `fuelCardInfo`, `consumeSummaryNumber` may be set.
 */
export interface DocumentDataType {
  /**
   * Sequential number of the original document or modification document
   *
   * Dokumentum vagy módosító okirat sorszáma
   */
  documentNumber: string;
  /**
   * Date of issue of the document or the modification document
   *
   * Dokumentum vagy módosító okirat kelte
   */
  documentIssueDate: string;
  /**
   * Timestamp, the exact time of the document's opening according to the AE
   * clock
   *
   * Időbélyeg, a bizonylat nyitásának pontos ideje az AE órája szerint
   */
  issueStartDateTime: string;
  /**
   * Timestamp, the exact time of the document's closing according to the AE
   * clock
   *
   * Időbélyeg, a bizonylat zárásának pontos ideje az AE órája szerint
   */
  issueEndDateTime: string;
  /**
   * Health found information
   *
   * Egészségkártya információk
   */
  healthFundInfo?: HealthFundInfoType;
  /**
   * Fuel card information
   *
   * Üzemanyagkártya információk
   */
  fuelCardInfo?: FuelCardInfoType;
  /**
   * Consume summary's unique identifier
   *
   * Fogyasztásösszesítő egyedi azonosítója
   */
  consumeSummaryNumber?: string;
  /**
   * Information to describe document data
   *
   * Dokumentum adatok leírására szolgáló információk
   */
  document: DocumentType;
}

/**
 * Document detail data type
 *
 * Dokumentum részletező adatok típus
 */
export interface DocumentDetailType {
  /**
   * Type of document, in case of amending document, type of original document
   *
   * A bizonylat típusa, módosító okirat esetén az eredeti bizonylat típusa
   */
  documentCategory: DocumentCategoryType;
  /**
   * Payment instruments type
   *
   * Fizetőeszközök típusa
   */
  paymentInstruments: InstrumentType;
  /**
   * Type for additional data description
   *
   * További adat leírására szolgáló típus
   *
   * @remarks At most 100 entries.
   */
  additionalDocumentData?: EreceiptBaseAdditionalDataType[];
}

/**
 * Data in header of document type
 *
 * Dokumentum fejléc adatai típus
 */
export interface DocumentHeadType {
  /**
   * e-Cash register location of operation
   *
   * Az e-pénztárgép üzemeltetési helye
   */
  shop: ShopType;
  /**
   * e-Cash register taxpayer data, in case of a fuel owner two-operator e-cash
   * register used on a fuel well
   *
   * e-Pénztárgép üzemeltető adatai, üzemanyagkúton használt kétvállalkozós
   * e-pénztárgép esetén az üzemanyag tulajdonos adózó adatai
   */
  taxPayer: TaxPayerType;
  /**
   * In case of a fuel owner two-operator e-cash register used on a fuel well
   *
   * Üzemanyagkúton használt kétvállalkozós e-pénztárgépen az üzemeltető adózó
   * adatai
   */
  coTaxPayer?: TaxPayerType;
  /**
   * Data related to the customer
   *
   * Vevő adatai
   */
  customerInfo?: EreceiptBaseCustomerInfoType;
  /**
   * Document detail data
   *
   * Dokumentum részletező adatok
   */
  documentDetail: DocumentDetailType;
}

/**
 * Document operation type
 *
 * Dokumentum művelet típus
 */
export type DocumentOperationType = 'CREATE' | 'MODIFY' | 'STORNO';

/**
 * Modification or cancellation reference data type
 *
 * A módosítás vagy érvénytelenítés hivatkozási adatai típus
 *
 * @remarks At most one of `cancellationReason`, `modificationReason` may be set.
 */
export interface DocumentReferenceType {
  /**
   * Sequence number of the original document, on which the modification occurs -
   * section 170 (1) c) of the VAT law
   *
   * Az eredeti dokumentum sorszáma, melyre a módosítás vonatkozik - ÁFA tv. 170.
   * § (1) c)
   */
  originalDocumentNumber: string;
  /**
   * The unique sequence number referring to the original document
   *
   * A számlára vonatkozó módosító okirat egyedi sorszáma
   */
  modificationIndex: number;
  /**
   * Reason of the cancellation
   *
   * Sztornózás oka
   */
  cancellationReason?: CancellationReasonType;
  /**
   * Reason of the modification
   *
   * Módosítás oka
   */
  modificationReason?: ModificationReasonType;
}

export interface DocumentRequest {
  /**
   * Identifier of the request/response, unique with the taxnumber in every data
   * exchange transaction
   *
   * A kérés/válasz azonosítója, minden üzenetváltásnál - adószámonként - egyedi
   */
  requestId: string;
  /**
   * UTC time of the request/response
   *
   * A kérés/válasz keletkezésének UTC ideje
   */
  timestamp: string;
  /**
   * Request version number, indicating which datastructure the client sends data
   * in, and in which the response is expected
   *
   * A kérés/válasz verziószáma, hogy a hívó melyik interfész verzió szerint küld
   * adatot és várja a választ
   */
  requestVersion: string;
  /**
   * Header version number
   *
   * A header verziószáma
   */
  headerVersion?: string;
  /**
   * e-Cash register AP number
   *
   * e-Pénztárgép AP száma
   */
  APNumber: string;
  /**
   * The first 8 characters of the tax number of the taxpayer who creates the
   * document, or (if part of a VAT group) the first 8 characters of the member
   * tax number of the taxpayer who creates the document.
   *
   * A bizonylatot kiállító adózó adószámának első 8 karaktere, vagy ÁFA-csoport
   * tagság esetén a bizonylatot kiállító adózó tagi adószámának első 8
   * karaktere.
   */
  taxNumber: string;
  /**
   * The first 8 characters of the group identification number of the taxpayer
   * who creates the document (if part of a VAT group).
   *
   * ÁFA-csoport tagság esetén a bizonylatot kiállító adózó csoportazonosító
   * számának első 8 karaktere.
   */
  groupIdentificationNumber?: string;
  /**
   * The type of the document (recipt, invoice, simplified invoice, etc.)
   *
   * A beküldött bizonylat típusa (nyugta, számla, egyszerűsített számla, stb.)
   */
  documentClass: DocumentClassType;
  /**
   * The document data for the customer and the NAV in the format described in
   * Development Documentation.
   *
   * A bizonylat NAV-nak és vevőnek átadandó adatai a Fejlesztői dokumentációban
   * meghatározott formátumban.
   */
  documentEnvelope: SignedDocumentEnvelopeType;
  /**
   * Independent symmetric key for encryption of receipt data.
   *
   * Független szimetrikus kulcs a bizonylat adatok kititkosításához.
   */
  decryptKey: string;
  /**
   * The document can be queried by this data from the Document Store. It
   * contains the document creation timestamp.
   *
   * A nyugtatárból ezzel az időbélyeggel kérdezhető le a bizonylat. A bizonylat
   * kiállításának időpontját tartalmazza.
   */
  searchKeyTimestamp: string;
  /**
   * The document can be queried by this data from the Document Store.
   *
   * A nyugtatárból ezzel a kulccsal kérdezhető le a bizonylat.
   */
  searchKey: string;
  /**
   * QR code generate timestamp expired.
   *
   * A QR generálása a fejlesztői dokumentációban meghatározott időintervallumnál
   * régebben készült .
   */
  qRCodeExpired: boolean;
  /**
   * Whether the document was created offline. When the communication network is
   * online again, the document has to be sent immidiately, with this flag.
   *
   * A hírközlő hálózat elérhetetlenségének megszűnése esetén az érintett
   * bizonylatokat és adatszolgáltatásokat haladéktalanul el kell küldeni, a
   * késleltetett küldés tényét ennek a mezőnek a kitöltésével kell jelezni.
   */
  offlineCreated: boolean;
  /**
   * The sign certificate of the e-cash register in DER format. The private key
   * of this certificate has to be used to sign the messages of the e-cash
   * register. The requirements of the sign key can be found in the "Signing"
   * chapter of the Development Documentation.
   *
   * Az e-pénztárgép aláíró tanúsítványa DER formátumban. A tanúsítvány privát
   * kulcsával kerülnek aláírásra az e-pénztárgép által küldött üzenetek. Az
   * aláíró kulccsal kapcsolatos követelmények a Fejlesztői dokumentáció „Aláírás
   * képzése” fejezetében találhatók.
   */
  cashRegisterSignCertificate: string;
  /**
   * The recordCounter value of the actual document. See further information in
   * the "Generate NAV verification code" chapter of the Development
   * Documentation.
   *
   * Az aktuálisan beküldött bizonylat recordCounter értéke. Leírását lásd a
   * Fejlesztői dokumentáció „NAV ellenőrző kód képzése” fejezetében.
   */
  recordCounter: number;
  /**
   * The recordCounter value of the last document in the e-cash register. See
   * further information in the "Generate NAV verification code" chapter of the
   * Development Documentation.
   *
   * Az e-pénztárgépen utoljára kiállított bizonylat recordCounter értéke.
   * Leírását lásd a Fejlesztői dokumentáció „NAV ellenőrző kód képzése”
   * fejezetében.
   */
  lastRecordCounter: number;
  /**
   * Ntca verification code. See further information in the "Generate NAV
   * verification code" chapter of the Development Documentation.
   *
   * NAV ellenőrző kód. Leírását lásd a Fejlesztői dokumentáció „NAV ellenőrző
   * kód képzése” fejezetében.
   */
  ntcaVerificationCode: string;
  /**
   * If the document is sent due to the execution of the SEND_MISSING_DOCUMENT
   * command, the process ID received in it must be entered here. It is not
   * required for normal submission.
   *
   * Amennyiben a bizonylat beküldése a SEND_MISSING_DOCUMENT felszólítás
   * végrehajtásaként történik, akkor itt kell megadni az abban kapott folyamat
   * azonosítót. Normál beküldés esetén nem kell megadni.
   */
  sendMissingDocumentProcessId?: string;
}

