/**
 * Field type including data of invoice items (product or service)
 *
 * A számla tételek (termék vagy szolgáltatás) adatait tartalmazó típus
 *
 * @remarks At most one of `lineAmountsNormal`, `lineAmountsSimplified` may be set.
 */
export interface DataLineType {
  /**
   * Sequential number of the item
   *
   * A tétel sorszáma
   */
  lineNumber: number;
  /**
   * Marking the goal of modification of the line (in the case of data supply
   * about changes/updates only)
   *
   * Módosításról történő adatszolgáltatás esetén a tételsor módosítás jellegének
   * jelölése
   */
  lineModificationReference?: LineModificationReferenceType;
  /**
   * References to connected items if it is necessary according to VAT law
   *
   * Hivatkozások kapcsolódó tételekre, ha ez az ÁFA törvény alapján szükséges
   */
  referencesToOtherLines?: ReferencesToOtherLinesType;
  /**
   * Advance related data
   *
   * Előleghez kapcsolódó adatok
   */
  advanceData?: AdvanceDataType;
  /**
   * Product codes
   *
   * Termékkódok
   */
  productCodes?: DataProductCodesType;
  /**
   * The value is true if the unit of measure of the invoice item is expressible
   * in natural unit
   *
   * Értéke true, ha a tétel mennyiségi egysége természetes mértékegységben
   * kifejezhető
   */
  lineExpressionIndicator: boolean;
  /**
   * Indication of the nature of the supply of goods or services on a given line
   *
   * Adott tételsor termékértékesítés vagy szolgáltatás nyújtás jellegének
   * jelzése
   */
  lineNatureIndicator?: DataLineNatureIndicatorType;
  /**
   * Name / description of the product or service
   *
   * A termék vagy szolgáltatás megnevezése
   */
  lineDescription?: string;
  /**
   * Quantity
   *
   * Mennyiség
   */
  quantity?: string;
  /**
   * Canonical representation of the unit of measure of the invoice, according to
   * the interface specification
   *
   * A számlán szereplő mennyiségi egység kanonikus kifejezése az interfész
   * specifikáció szerint
   */
  unitOfMeasure?: DataUnitOfMeasureType;
  /**
   * Literal unit of measure of the invoice
   *
   * A számlán szereplő mennyiségi egység literális kifejezése
   */
  unitOfMeasureOwn?: string;
  /**
   * Unit price expressed in the currency of the invoice In the event of
   * simplified invoices gross unit price, in other cases net unit price
   *
   * Egységár a számla pénznemében. Egyszerűsített számla esetén bruttó, egyéb
   * esetben nettó egységár
   */
  unitPrice?: string;
  /**
   * Unit price expressed in HUF
   *
   * Egységár forintban
   */
  unitPriceHUF?: string;
  /**
   * Discount data in relation to the item
   *
   * A tételhez tartozó árengedmény adatok
   */
  lineDiscountData?: DiscountDataType;
  /**
   * Item value data to be completed in case of normal (not simplified, but
   * including aggregated) invoice
   *
   * Normál (nem egyszerűsített) számla esetén (beleértve a gyűjtőszámlát)
   * kitöltendő tétel érték adatok.
   */
  lineAmountsNormal?: LineAmountsNormalType;
  /**
   * Item value data to be completed in case of simplified invoice
   *
   * Egyszerűsített számla esetén kitöltendő tétel érték adatok
   */
  lineAmountsSimplified?: LineAmountsSimplifiedType;
  /**
   * The value is true if the item is an intermediated service - paragraph (4) 1
   * of the Article 3 of Accounting Act
   *
   * Értéke true ha a tétel közvetített szolgáltatás - Számviteli tv. 3.§ (4) 1
   */
  intermediatedService?: boolean;
  /**
   * Aggregate invoice data
   *
   * Gyűjtő számla adatok
   */
  aggregateInvoiceLineData?: AggregateInvoiceLineDataType;
  /**
   * Supply of new means of transport - section 89 § and 169 (o) of the VAT law
   *
   * Új közlekedési eszköz értékesítés ÁFA tv. 89 § ill. 169 § o)
   */
  newTransportMean?: NewTransportMeanType;
  /**
   * The value is true if the item is bottle/container deposit
   *
   * Értéke true, ha a tétel betétdíj jellegű
   */
  depositIndicator?: boolean;
  /**
   * The value is true if the item is liable to product fee
   *
   * Értéke true ha a tételt termékdíj fizetési kötelezettség terheli
   */
  obligatedForProductFee?: boolean;
  /**
   * Excise duty on natural gas, electricity and coal in Hungarian forints –
   * paragraph (2), Section 118 of the Act on Excise Duties
   *
   * Földgáz, villamos energia, szén jövedéki adója forintban - Jöt. 118. § (2)
   */
  GPCExcise?: string;
  /**
   * Data of gas oil acquisition after taxation – point a), paragraph (1) of
   * Section 75 of the NGM Decree No. 45/2016. (XI. 29.)
   *
   * Gázolaj adózottan történő beszerzésének adatai – 45/2016 (XI. 29.) NGM
   * rendelet 75. § (1) a)
   */
  dieselOilPurchase?: DieselOilPurchaseType;
  /**
   * Value is true, if the taxable person is liable for tax obligation determined
   * in the Act on Public Health Product Tax (Neta tv.). Paragraph (2), Section 3
   * of the Act CIII of 2011
   *
   * Értéke true, ha a Neta tv-ben meghatározott adókötelezettség az adó alanyát
   * terheli. 2011. évi CIII. tv. 3.§(2)
   */
  netaDeclaration?: boolean;
  /**
   * Clauses according to the Act LXXXV of 2011 on Environmental Protection
   * Product Fee (related to the item)
   *
   * A környezetvédelmi termékdíjról szóló 2011. évi LXXXV. tv. szerinti, tételre
   * vonatkozó záradékok
   */
  productFeeClause?: ProductFeeClauseType;
  /**
   * Data on the content of the line's product charge
   *
   * A tétel termékdíj tartalmára vonatkozó adatok
   */
  lineProductFeeContent?: ProductFeeDataType[];
  /**
   * Other conventionally named data to assist in invoice processing
   *
   * A számlafeldolgozást segítő, egyezményesen nevesített egyéb adatok
   */
  conventionalLineInfo?: ConventionalInvoiceInfoType;
  /**
   * Other data in relation to the product / service item
   *
   * A termék/szolgáltatás tételhez kapcsolódó, további adat
   */
  additionalLineData?: DataAdditionalDataType[];
}

